var _uuid_parse = (inp, uu) => {
  // int uuid_parse(const char *in, uuid_t uu);
  inp = UTF8ToString(inp);
  if (inp.length === 36) {
    var i = 0;
    var uuid = new Array(16);
    inp.toLowerCase().replace(/[0-9a-f]{2}/g, function(byte) {
      if (i < 16) {
        uuid[i++] = parseInt(byte, 16);
      }
    });
    if (i < 16) {
      return -1;
    }
    writeArrayToMemory(uuid, uu);
    return 0;
  }
  return -1;
};

